 "math.h": "#pragma once\n\n#ifndef __NO_FLONUM\n#define M_PI        (3.14159265358979323846)\n#define M_PI_2      (1.57079632679489661923)\n#define M_PI_4      (0.78539816339744830962)\n#define M_1_PI      (1.0 / M_PI)\n#define M_2_PI      (2.0 / M_PI)\n#define M_2_SQRTPI  (1.128379167095513)\n#define M_SQRT2     (1.414213562373095)\n#define M_SQRT1_2   (0.707106781186548)\n#define M_E         (2.718281828459045)\n#define M_LOG2E     (1.442695040888963)\n#define M_LOG10E    (0.434294481903252)\n#define M_LN2       (0.693147180559945)\n#define M_LN10      (2.302585092994046)\n#define NAN         (__builtin_nan(\"0x7ff8000000000000\"))\n#define INFINITY    (1.0 / 0.0)\n#define HUGE_VAL    INFINITY\n\n#if defined(__riscv) || defined(__wasm)  // newlib environments.\n#define FP_NAN        0\n#define FP_INFINITE   1\n#define FP_ZERO       2\n#define FP_SUBNORMAL  3\n#define FP_NORMAL     4\n#else\n\n#define FP_NAN        1\n#define FP_INFINITE   2\n#define FP_ZERO       3\n#define FP_NORMAL     4\n#define FP_SUBNORMAL  5\n#endif\n\ndouble sin(double);\ndouble cos(double);\ndouble tan(double);\ndouble asin(double);\ndouble acos(double);\ndouble atan(double);\ndouble atan2(double y, double x);\ndouble sinh(double);\ndouble cosh(double);\ndouble tanh(double);\ndouble asinh(double);\ndouble acosh(double);\ndouble atanh(double);\ndouble sqrt(double);\ndouble log(double x);\ndouble log10(double x);\ndouble log2(double x);\ndouble exp(double x);\ndouble pow(double base, double x);\ndouble fabs(double);\ndouble floor(double);\ndouble ceil(double x);\ndouble round(double x);\ndouble modf(double x, double *pint);\ndouble fmod(double x, double m);\ndouble frexp(double x, int *p);\ndouble ldexp(double x, int exp);\ndouble scalbn(double x, int exp);\n\nfloat fabsf(float);\nlong double fabsl(long double x);\n\nint finite(double x);\n\nstatic inline int signbit(double x) {\n#if defined(__APPLE__) || defined(__riscv)\n  extern int __signbitd(double);\n  return __signbitd(x);\n#else\n  extern int __signbit(double x);\n  return __signbit(x);\n#endif\n}\n\ndouble copysign(double x, double f);\n\nstatic inline int fpclassify(double x) {\n#if defined(__APPLE__) || defined(__riscv)\n  extern int __fpclassifyd(double);\n  return __fpclassifyd(x);\n#else\n  extern int __fpclassify(double x);\n  return __fpclassify(x);\n#endif\n}\n\nstatic inline int isfinite(double x) {\n#if defined(__APPLE__)\n  extern int __isfinited(double);\n  return __isfinited(x);\n#elif defined(__riscv)\n  int c = fpclassify(x);\n  return c != FP_INFINITE && c != FP_NAN;\n#else\n  return finite(x);\n#endif\n}\n\nstatic inline int isnan(double x) {\n#if defined(__APPLE__)\n  extern int __isnand(double);\n  return __isnand(x);\n#elif defined(__riscv) || defined(__wasm)\n  return fpclassify(x) == FP_NAN;\n#else\n  extern int __isnan(double);\n  return __isnan(x);\n#endif\n}\n\nstatic inline int isinf(double x) {\n#if defined(__APPLE__)\n  extern int __isinfd(double);\n  return __isinfd(x);\n#elif defined(__riscv) || defined(__wasm)\n  return fpclassify(x) == FP_INFINITE;\n#else\n  extern int __isinf(double);\n  return __isinf(x);\n#endif\n}\n\n#endif\n",
