 "sys/stat.h": "#pragma once\n\n#include <time.h>  // timespec\n#include <stddef.h>  // size_t\n#include <stdint.h>\n#include <sys/types.h>  // off_t\n\ntypedef unsigned long ino_t;\ntypedef uint32_t uid_t;\ntypedef uint32_t gid_t;\ntypedef unsigned long blkcnt_t;\n\n#if defined(__APPLE__)\ntypedef int32_t dev_t;\ntypedef uint16_t mode_t;\ntypedef uint16_t nlink_t;\ntypedef int32_t blksize_t;\n\n// __DARWIN_STRUCT_STAT64\nstruct stat {\n  dev_t       st_dev;                 /* [XSI] ID of device containing file */\n  mode_t      st_mode;                /* [XSI] Mode of file (see below) */\n  nlink_t     st_nlink;               /* [XSI] Number of hard links */\n  uint64_t    st_ino;                 /* [XSI] File serial number */\n  uid_t       st_uid;                 /* [XSI] User ID of the file */\n  gid_t       st_gid;                 /* [XSI] Group ID of the file */\n  dev_t       st_rdev;                /* [XSI] Device ID */\n\n  // __DARWIN_STRUCT_STAT64_TIMES\n  struct timespec st_atimespec;           /* time of last access */\n  struct timespec st_mtimespec;           /* time of last data modification */\n  struct timespec st_ctimespec;           /* time of last status change */\n  struct timespec st_birthtimespec;       /* time of file creation(birth) */\n\n  off_t       st_size;                /* [XSI] file size, in bytes */\n  blkcnt_t    st_blocks;              /* [XSI] blocks allocated for file */\n  blksize_t   st_blksize;             /* [XSI] optimal blocksize for I/O */\n  uint32_t    st_flags;               /* user defined flags for file */\n  uint32_t    st_gen;                 /* file generation number */\n  int32_t     st_lspare;              /* RESERVED: DO NOT USE! */\n  int64_t     st_qspare[2];           /* RESERVED: DO NOT USE! */\n};\n#elif defined(__x86_64__)\ntypedef unsigned long dev_t;\ntypedef int mode_t;\ntypedef unsigned long nlink_t;\ntypedef unsigned long blksize_t;\n\nstruct stat {\n  dev_t     st_dev;\n  ino_t     st_ino;\n  nlink_t   st_nlink;\n  mode_t    st_mode;\n  uid_t     st_uid;\n  gid_t     st_gid;\n  int __pad0;\n  dev_t     st_rdev;\n  off_t     st_size;\n  blksize_t st_blksize;\n  blkcnt_t  st_blocks;\n\n  struct timespec st_atim;\n  struct timespec st_mtim;\n  struct timespec st_ctim;\n\n#define st_atime st_atim.tv_sec\n#define st_mtime st_mtim.tv_sec\n#define st_ctime st_ctim.tv_sec\n\n  /*__syscall_slong_t*/ long __glibc_reserved[3];\n};\n\n#else\ntypedef unsigned long dev_t;\ntypedef int mode_t;\ntypedef unsigned int nlink_t;\ntypedef unsigned long blksize_t;\n\nstruct stat {\n  dev_t     st_dev;\n  ino_t     st_ino;\n  mode_t    st_mode;\n  nlink_t   st_nlink;\n  uid_t     st_uid;\n  gid_t     st_gid;\n  dev_t     st_rdev;\n  dev_t __pad1;\n  off_t     st_size;\n  blksize_t st_blksize;\n  blkcnt_t  st_blocks;\n\n  struct timespec st_atim;\n  struct timespec st_mtim;\n  struct timespec st_ctim;\n\n#define st_atime st_atim.tv_sec\n#define st_mtime st_mtim.tv_sec\n#define st_ctime st_ctim.tv_sec\n\n  int __glibc_reserved[2];\n};\n#endif\n\nint mkdir(const char *pathname, mode_t mode);\nint mkdirat(int dirfd, const char *pathname, mode_t mode);\n\nint chmod(const char *pathname, mode_t mode);\nint fchmodat(int dirfd, const char *pathname, mode_t mode, int flags);\n\n#define S_IFMT    0170000\n#define S_IFIFO   0010000\n#define S_IFCHR   0020000\n#define S_IFDIR   0040000\n#define S_IFBLK   0060000\n#define S_IFREG   0100000\n#define S_IFLNK   0120000\n#define S_IFSOCK  0140000\n\n#define S_ISREG(m)   (((m) & S_IFMT) == S_IFREG)\n#define S_ISDIR(m)   (((m) & S_IFMT) == S_IFDIR)\n#define S_ISCHR(m)   (((m) & S_IFMT) == S_IFCHR)\n#define S_ISBLK(m)   (((m) & S_IFMT) == S_IFBLK)\n#define S_ISLNK(m)   (((m) & S_IFMT) == S_IFLNK)\n#define S_ISSOCK(m)  (((m) & S_IFMT) == S_IFSOCK)\n#define S_ISFIFO(m)  (((m) & S_IFMT) == S_IFFIFO)\n\nint stat(const char *pathname, struct stat *buf);\nint fstat(int fd, struct stat *buf);\nint lstat(const char *pathname, struct stat *buf);\nint fstatat(int fd, const char *pathname, struct stat *buf, int flag);\n\n#if defined(__APPLE__)\n// Patch for Rosetta2/x64\nint stat64(const char *pathname, struct stat *buf);\nint fstat64(int fd, struct stat *buf);\nint lstat64(const char *pathname, struct stat *buf);\nint fstatat64(int fd, const char *pathname, struct stat *buf, int flag);\n#define stat(pathname, buf)   stat64(pathname, buf)\n#define fstat(pathname, buf)  fstat64(pathname, buf)\n#define lstat(pathname, buf)  lstat64(pathname, buf)\n#define fstatat(fd, p, b, f)  fstatat64(fd, p, b, f)\n#endif\n",
 "sys/types.h": "#pragma once\n\ntypedef long ssize_t;\n\ntypedef long off_t;\n\n#if !defined(__wasm)\ntypedef int pid_t;\n#endif\n",
 "sys/wait.h": "#pragma once\n\n#if !defined(__wasm)\n#include <sys/types.h>  // pid_t\n\n#define _WSTOPPED       0x7f\n#define WEXITSTATUS(x)  (((x) >> 8) & 0xff)\n#define WTERMSIG(x)     ((x) & 0x7f)\n#define WSTOPSIG(x)     ((x) >> 8)\n#define WIFEXITED(x)    (WTERMSIG(x) == 0)\n#define WIFSIGNALED(x)  (WTERMSIG(x) != _WSTOPPED && WTERMSIG(x) != 0)  // (((signed char) (((status) & 0x7f) + 1) >> 1) > 0)\n\n#if defined(__APPLE__)\n#define WIFSTOPPED(x)   (WTERMSIG(x) == _WSTOPPED && WSTOPSIG(x) != 0x13)\n#define WIFCONTINUED(x) (_WSTATUS(x) == _WSTOPPED && WSTOPSIG(x) == 0x13)\n\n#else\n#define __W_CONTINUED   0xffff\n#define WIFSTOPPED(x)   (WTERMSIG(x) == _WSTOPPED)\n#define WIFCONTINUED(x) ((x) == __W_CONTINUED)\n#endif\n\nstruct rusage;\n\npid_t wait(int *status);\npid_t waitpid(pid_t, int*, int);\npid_t wait4(pid_t pid, int *status, int options, struct rusage *usage);\n#endif\n",
 "time.h": "#pragma once\n\ntypedef long time_t;\n\nstruct timespec {\n  time_t tv_sec;\n  long tv_nsec;\n};\n\ntypedef enum {\n  CLOCK_REALTIME = 0,\n  CLOCK_REALTIME_COARSE = 5,\n} clockid_t;\n\ntime_t time(time_t *timer);\nint clock_gettime(clockid_t clk_id, struct timespec *tp);\n",
 "unistd.h": "#pragma once\n\n#include <stddef.h>  // size_t\n#include <stdint.h>  // intptr_t, uint64_t\n#include <sys/types.h>  // ssize_t, pid_t, off_t\n\n#define STDIN_FILENO   (0)\n#define STDOUT_FILENO  (1)\n#define STDERR_FILENO  (2)\n\nstruct clone_args {\n  uint64_t flags;        /* Flags bit mask */\n  uint64_t pidfd;        /* Where to store PID file descriptor\n                            (int *) */\n  uint64_t child_tid;    /* Where to store child TID,\n                            in child's memory (pid_t *) */\n  uint64_t parent_tid;   /* Where to store child TID,\n                            in parent's memory (pid_t *) */\n  uint64_t exit_signal;  /* Signal to deliver to parent on\n                            child termination */\n  uint64_t stack;        /* Pointer to lowest byte of stack */\n  uint64_t stack_size;   /* Size of stack */\n  uint64_t tls;          /* Location of new TLS */\n  uint64_t set_tid;      /* Pointer to a pid_t array\n                            (since Linux 5.5) */\n  uint64_t set_tid_size; /* Number of elements in set_tid\n                            (since Linux 5.5) */\n  uint64_t cgroup;       /* File descriptor for target cgroup\n                            of child (since Linux 5.7) */\n};\n\nssize_t write(int fd, const void *str, size_t len);\nint close(int fd);\nssize_t read(int fd, void *buf, size_t size);\noff_t lseek(int fd, off_t offset, int whence);\nint unlink(const char *pathname);\nint rmdir(const char *pathname);\nchar *getcwd(char *buffer, size_t size);\nint chdir(const char *path);\n\nint brk(void *addr);\nvoid *sbrk(intptr_t increment);\n\n#if !defined(__wasm)\nint unlinkat(int dirfd, const char *pathname, int flags);\nint dup(int);\nint pipe(int*);\nint pipe2(int *pipefd, int flag);\nint isatty(int fd);\n\npid_t fork(void);\nlong clone3(struct clone_args *cl_args, size_t size);\nint execvp(const char *, char *const[]);\nint execve(const char *, char *const[], char *const[]);\n\npid_t getpid(void);\npid_t getppid(void);\n#endif\n",
